210: function loadState() {
211:   const saved = localStorage.getItem("joy_blob_state");
212:   if (saved) {
213:     try {
214:       state = JSON.parse(saved);
215:       
216:       // Force reset legacy storage state for all devices
217:       if (!state.version || state.version !== "2.4") {
218:         state = JSON.parse(JSON.stringify(DEFAULT_STATE));
219:         state.lastResetDate = new Date().toDateString();
220:         saveState();
221:         return;
222:       }
223: 
224:       state.inventory = state.inventory || {};
225:       const mergeKeys = (target, src) => {
226:         const res = { ...target };
227:         for (const k in src) {
228:           if (res[k] === undefined) res[k] = src[k];
229:         }
230:         return res;
231:       };
232:       state.ownedAccessories = mergeKeys(state.ownedAccessories || {}, DEFAULT_STATE.ownedAccessories);
233:       state.equippedAccessories = mergeKeys(state.equippedAccessories || {}, DEFAULT_STATE.equippedAccessories);
234:       state.diaryLogs = state.diaryLogs || [];
235:       state.activeMoodQuests = state.activeMoodQuests || [];
236:       state.moodQuestProgress = state.moodQuestProgress || {};
237:       state.stressHistory = state.stressHistory || [];
238:       state.activePosition = state.activePosition || "pos-carpet";
239:       state.dailyGameExpEarned = state.dailyGameExpEarned || 0;
240:       state.isAngel = state.isAngel !== undefined ? state.isAngel : false;
241:       state.petGender = state.petGender !== undefined ? state.petGender : "";
242:       state.isRebirthTriggered = state.isRebirthTriggered !== undefined ? state.isRebirthTriggered : false;
243:       
244:       checkDailyReset();
245:     } catch (e) {
246:       console.error("Error loading state, resetting...", e);
247:       state = { ...DEFAULT_STATE };
248:       saveState();
249:     }
250:   } else {
251:     state = { ...DEFAULT_STATE };
252:     state.lastResetDate = new Date().toDateString();
253:     saveState();
254:   }
255: }
